inline void enc_response_metadata(std::string& out, const ResponseMetadata& v, int depth) {
    out += '{';
    bool first = true;
    if (!v.code.empty()) {
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "code");
        out += ": ";
        esc(out, v.code);
    }
    if (!v.error.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "error");
        out += ": ";
        esc(out, v.error);
    }
    if (!v.secret.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "secret");
        out += ": ";
        esc(out, v.secret);
    }
    if (!v.token.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "token");
        out += ": ";
        esc(out, v.token);
    }
    if (!v.expires.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "expires");
        out += ": ";
        esc(out, v.expires);
    }
    if (v.app.has_value()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "app");
        out += ": ";
        enc_app_metadata(out, *v.app, depth + 1);
    }
    if (!v.right.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "right");
        out += ": ";
        esc(out, v.right);
    }
    if (!v.apps.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "apps");
        out += ": ";
        enc_list<AppMetadata>(out, v.apps, depth + 1, enc_app_metadata);
    }
    if (!v.holds.empty()) {
        if (!first) out += ',';
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "holds");
        out += ": ";
        enc_list<HoldMetadata>(out, v.holds, depth + 1, enc_hold_metadata);
    }
    if (!first) { out += '\n'; pad(out, depth); }
    out += '}';
}

